{
  "root": "main_stack",
  "state": {
    "itinerary": [
      {
        "time": "09:00 - 10:30",
        "activity": "Keynote: The Future of Cloud",
        "location": "Main Hall"
      },
      {
        "time": "10:45 - 12:00",
        "activity": "Deep Dive: Kubernetes Networking",
        "location": "Room A"
      },
      {
        "time": "12:15 - 13:30",
        "activity": "Lunch & Networking",
        "location": "Dining Hall"
      },
      {
        "time": "13:30 - 15:30",
        "activity": "Zero Trust Architecture Workshop",
        "location": "Room C"
      },
      {
        "time": "15:30 - 16:15",
        "activity": "Automated CI/CD Pipelines (Late Entry)",
        "location": "Room B"
      },
      {
        "time": "16:30 - 17:00",
        "activity": "Closing Remarks",
        "location": "Main Hall"
      }
    ],
    "conflicts": [
      {
        "conflict": "Kubernetes Networking (Room A) overlaps with Securing Serverless (Room B).",
        "resolution": "Priority: Kubernetes Networking for core infrastructure depth."
      },
      {
        "conflict": "Scaling Databases (Room A) overlaps with Zero Trust Workshop (Room C).",
        "resolution": "Priority: Zero Trust for advanced security track requirements."
      },
      {
        "conflict": "Zero Trust Workshop (Room C) overlaps with CI/CD Pipelines (Room B).",
        "resolution": "Resolution: Complete the workshop and join the CI/CD session at 15:30."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_text",
        "description_text",
        "hero_image",
        "itinerary_header_stack",
        "itinerary_table",
        "conflicts_heading",
        "conflicts_table",
        "actions_heading",
        "actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Cloud Architecture Summit: Austin 2024",
        "variant": "h1"
      },
      "children": []
    },
    "description_text": {
      "type": "Text",
      "props": {
        "text": "This itinerary for Senior DevOps Engineers prioritizes Kubernetes networking and enterprise security workshops, ensuring coverage of critical infrastructure and zero-trust principles."
      },
      "children": []
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Austin_Skyline_2010.jpg/1200px-Austin_Skyline_2010.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "itinerary_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "itinerary_icon",
        "itinerary_heading"
      ]
    },
    "itinerary_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/laptop.svg"
      },
      "children": []
    },
    "itinerary_heading": {
      "type": "Text",
      "props": {
        "text": "DevOps & Security Recommended Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary",
        "columns": [
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          },
          {
            "key": "location",
            "label": "Location"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "activity",
        "highlightColumns": ["time", "location"]
      },
      "children": []
    },
    "conflicts_heading": {
      "type": "Text",
      "props": {
        "text": "Scheduling Conflicts & Resolution",
        "variant": "h2"
      },
      "children": []
    },
    "conflicts_table": {
      "type": "Table",
      "props": {
        "statePath": "/conflicts",
        "columns": [
          {
            "key": "conflict",
            "label": "Conflict"
          },
          {
            "key": "resolution",
            "label": "Resolution"
          }
        ],
        "domain": "status",
        "preferredPresentation": "cards",
        "primaryColumn": "conflict",
        "highlightColumns": ["resolution"]
      },
      "children": []
    },
    "actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "justify": "start",
        "wrap": "wrap"
      },
      "children": [
        "materials_button",
        "slack_button"
      ]
    },
    "materials_button": {
      "type": "Button",
      "props": {
        "label": "Session Materials"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://cloudsummit-austin.io/resources"
          }
        }
      },
      "children": []
    },
    "slack_button": {
      "type": "Button",
      "props": {
        "label": "Join Slack Track"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://cloudsummit-austin.io/devops-slack"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "schedule_button",
        "convention_button"
      ]
    },
    "schedule_button": {
      "type": "Button",
      "props": {
        "label": "Summit Agenda",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://cloudsummit-austin.io/schedule"
          }
        }
      },
      "children": []
    },
    "convention_button": {
      "type": "Button",
      "props": {
        "label": "Austin Convention Bureau",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.austintexas.org/austin-convention-center/"
          }
        }
      },
      "children": []
    }
  }
}
